use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::Intent;

struct Node;

fn parse_intent(raw: &str) -> Intent {
    let normalized = raw.trim().to_lowercase();
    if normalized.contains("billing_question") || normalized.contains("billing") {
        Intent::BillingQuestion
    } else if normalized.contains("technical_support") || normalized.contains("technical") {
        Intent::TechnicalSupport
    } else if normalized.contains("account_change") || normalized.contains("account") {
        Intent::AccountChange
    } else if normalized.contains("general_inquiry") || normalized.contains("general") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

fn truncate_to_chars(s: &str, max_chars: usize) -> String {
    s.chars().take(max_chars).collect()
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let system = "Classify the customer's message into exactly one intent category. \
             Respond with exactly one of these words: billing_question, technical_support, \
             account_change, general_inquiry, unknown. Respond with nothing else.";

        let raw_intent = infer(system, &message.text, "classify");
        let intent = parse_intent(&raw_intent);

        let question = truncate_to_chars(&message.text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

